def longestDiverseString(a: int, b: int, c: int) -> str:
    res = []
    counts = {'a': a, 'b': b, 'c': c}

    while True:
        if sum(counts.values()) == 0:
            break

        sorted_chars = sorted(counts.keys(), key=lambda x: -counts[x])

        chosen = None
        for char in sorted_chars:
            if counts[char] == 0:
                continue
            if len(res) >= 2 and res[-1] == res[-2] == char:
                continue
            if len(res) >= 2 and res[:-1][0] == res[-1] == char:
                continue
            chosen = char
            break

        if chosen is None:
            break

        res.append(chosen)
        counts[chosen] -= 1

        if len(res) >= 2 and res[-1] == res[-1]:
            pass

    return "".join(res)
